class ReadOrdersTest(unittest.TestCase):
    ...

    def test_reads_prices_with_decimal_comma(self):
        # Regression: the 2026-10-02 export priced order A-1045 as "12,50" and "8,00";
        # 49bc16d stopped accepting the comma and the nightly import crashed.
        rows = (
            HEADER
            + "A-1045;ana@example.com;2026-10-01T16:02:00+02:00;TEA-12;1;12,50;\n"
            + "A-1045;ana@example.com;2026-10-01T16:02:00+02:00;MUG-02;2;8,00;\n"
        )
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "orders.csv"
            path.write_text(rows, encoding="utf-8")
            orders = importer.read_orders(path)
        self.assertEqual([line.unit_price for line in orders[0].lines], [Decimal("12.50"), Decimal("8.00")])
